def num_mock_patch_args(function):
    """ return number of arguments used up by mock arguments (if any) """
    patchings = getattr(function, "patchings", None)
    if not patchings:
        return 0
    mock_modules = [sys.modules.get("mock"), sys.modules.get("unittest.mock")]
    if any(mock_modules):
        sentinels = [m.DEFAULT for m in mock_modules if m is not None]
        return len(
            [
                p
                for p in patchings
                if not p.attribute_name
                # Use identity comparison instead of `in`: `p.new` may be an
                # object (e.g. a numpy array) whose `__eq__` returns a
                # non-boolean, which would raise when evaluated as truth value.
                and any(p.new is sentinel for sentinel in sentinels)
            ]
        )
    return len(patchings)


